pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 wd, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        wd = bound(wd, 1, 1e30);
        amount = bound(amount, 1 ether + wd, type(uint256).max - 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // let the lock time pass so withdrawal is admissible
        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        c.Collect(wd);

        // credited deposit funds the withdrawal: balance must drop from amount to amount - wd
        assertTrue(c.Acc(actor).balance == amount - wd);
    }
}

