pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount < address(actor).balance + type(uint256).max / 2 - 1);
        amount = bound(amount, 1, 1000 ether);

        vm.deal(actor, amount);
        uint256 before = address(c).balance;
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Universal rule: after any successful deposit of `amount`, the contract's
        // held ether equals prior balance plus the deposit, and the deposit is
        // credited to the depositor's account so it can be observed via the getter.
        assertTrue(
            address(c).balance == before + amount && c.Acc(actor).balance == amount
        );
    }
}

