pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 t, uint256 v, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        t = bound(t, block.timestamp + 1, block.timestamp + 365 days);
        v = bound(v, 1 ether, 100 ether);

        vm.deal(actor, v);
        vm.prank(actor);
        (bool okPut,) = address(c).call{value: v}(
            abi.encodeWithSelector(c.Put.selector, t)
        );
        vm.assume(okPut);

        // Time-lock rule: funds locked until t cannot be collected early.
        vm.prank(actor);
        (bool okCollect,) = address(c).call{value: 0}(
            abi.encodeWithSelector(c.Collect.selector, v)
        );
        assertTrue(!okCollect, "time-locked funds must not be collectable before unlockTime");
    }
}

