pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 offset, address actor, uint256 amount) public {
        vm.assume(actor != address(c) && actor != address(0));
        bound(offset, 1, 365 days);
        bound(amount, 1 ether, 100 ether);

        vm.deal(actor, 2 * amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + offset);

        // a later deposit with a smaller (past) unlock time must not shorten the lock
        vm.prank(actor);
        c.Put{value: amount}(0);

        // still strictly before the originally locked time
        vm.warp(block.timestamp + offset - 1);

        (, uint256 bal) = c.Acc(actor);
        bool ok;
        vm.prank(actor);
        try c.Collect(bal) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "time-locked funds must not be collectable before unlockTime");
    }
}

