pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        uint before = c.LogFile().History(c.LogFile().History.length - 0) == bytes32(0) ? 0 : 0;
        // read current history length via Log's public getter on c's LogFile
        // LogFile is internal, so query via Log at c's stored address is not exposed;
        // instead observe growth through History length read on a Log instance we control.
        // Deploy our own Log, pass to c:
        Log lg = new Log();
        c = new C(address(lg));
        uint lenBefore = lg.History(0) == lg.History(0) ? historyLen(lg) : 0;
        lenBefore = historyLen(lg);
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(historyLen(lg) == lenBefore + 1, "each successful Put logs exactly one entry");
    }

    function historyLen(Log lg) internal view returns (uint n) {
        // History is a public dynamic array; probe length via repeated getter calls.
        n = 0;
        while (true) {
            try this.probe(lg, n) {
                n++;
            } catch {
                return n;
            }
        }
    }

    function probe(Log lg, uint i) external view {
        lg.History(i);
    }
}

