pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(uint256 amount, uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(amount <= type(uint256).max / 2);
        bound(ts, 1, type(uint64).max);

        vm.warp(ts);
        vm.deal(actor, amount);
        uint256 beforeLen = log.History_length();

        vm.prank(actor);
        c.Put{value: amount}(ts);

        uint256 afterLen = log.History_length();
        (address sender, , uint256 val, ) = log.History(afterLen == 0 ? 0 : afterLen - 1);

        // Rule: every successful Put by any actor appends a Log entry matching
        // that Put (sender, value); the mutant's last entry does not match.
        assertTrue(beforeLen < afterLen && sender == actor && val == amount);
    }
}

